    function show(){zimg.src=img.src;layer.style.display='block';}
    function hide(){layer.style.display='none';}
    function move(e){
      var vw=window.innerWidth,vh=window.innerHeight,zw=320,zh=320,pad=14;
      var x=e.clientX+pad,y=e.clientY+pad;
      if(x+zw>vw-pad) x=e.clientX-zw-pad;
      if(y+zh>vh-pad) y=e.clientY-zh-pad;
      x=Math.max(pad,x);y=Math.max(pad,y);
      layer.style.left=x+'px';layer.style.top=y+'px';
    }
    box.addEventListener('mouseenter',function(e){show();move(e);});
    box.addEventListener('mousemove',move);
    box.addEventListener('mouseleave',hide);
  });
})();
